CAT_RE = [(c, re.compile(p)) for c, p in CATEGORIES]
TOWING_RE = re.compile(r"\b(TOW|TOWING|ROADSIDE|WRECKER|WRECKERS)\b")

def category_guess(name, entity_type=""):
    n = (name or "").upper()
    for c, r in CAT_RE:
        if r.search(n):
            return c
    if "NONPROFIT" in (entity_type or ""):
        return "Nonprofit, church & community"
    return "Other / unclear"

def is_towing(name):
    return bool(TOWING_RE.search((name or "").upper()))
